    {
      "keystrokes": "grep -n -E \"(authenticated|userauth|{connected|state)\" /app/workspace/otp_src_27.3.2/lib/ssh/src/ssh_connection_handler.erl | head -50\n",
      "duration": 0.5
    }
  ]
